namespace Tests;
public class CmsAdminTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Cms_pages_defaults_save_rename_conflict_publish_and_atomic_audit()
    {
        var admin=await Admin();var support=await Staff(admin,"cmssupport@example.test","support");Assert.Equal(403,(await support.Get("/api/admin/storefront/pages")).Status);var r=await admin.Get("/api/admin/storefront/pages");Assert.True(r.Status==200,r.ToString());Assert.NotEmpty(r.Json.AsArray());Assert.All(r.Json.AsArray(),x=>Assert.False(x!["saved"]!.GetValue<bool>()));var defaultSlug=r.Json[0]!["slug"]!.GetValue<string>();
        r=await admin.Put("/api/admin/storefront/pages/synthetic-page",new{slug="synthetic-page",title="Synthetic Page",body="# Synthetic body",meta_description="Synthetic description"});Assert.Equal(200,r.Status);Assert.Equal(200,(await admin.Get("/api/pages/synthetic-page")).Status);Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM audit_logs WHERE action='storefront.page'"));
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/pages/synthetic-page",new{slug="renamed-page",title="Renamed Page",body="Private draft",is_published=false})).Status);Assert.Equal(404,(await admin.Get("/api/pages/synthetic-page")).Status);Assert.Equal(404,(await admin.Get("/api/pages/renamed-page")).Status);
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/pages/another-page",new{slug="another-page",title="Another Page",body=""})).Status);Assert.Equal("slug_taken",(await admin.Put("/api/admin/storefront/pages/renamed-page",new{slug="another-page",title="Conflict Page",body=""})).ErrorCode);
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_cms_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='storefront.page' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic CMS rollback'; END IF; END");try{Assert.Equal(500,(await admin.Put("/api/admin/storefront/pages/renamed-page",new{slug="renamed-page",title="Must roll back",body="bad"})).Status);Assert.Equal("Renamed Page",await ApiFactory.DbScalarAsync<string>("SELECT title FROM cms_pages WHERE slug='renamed-page'"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_cms_fail");}
        Assert.Equal(422,(await admin.Put("/api/admin/storefront/pages/bad",new{slug="UPPER",title="Bad",body=""})).Status);Assert.Equal(422,(await admin.Put("/api/admin/storefront/pages/bad",new{slug="valid-slug",title="Bad"})).Status);
        Assert.Equal(200,(await admin.Delete("/api/admin/storefront/pages/renamed-page")).Status);Assert.Equal(200,(await admin.Delete("/api/admin/storefront/pages/renamed-page")).Status);Assert.Equal(0,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM cms_pages WHERE slug='renamed-page'"));
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/pages/"+defaultSlug,new{slug=defaultSlug,title="Synthetic Default Override",body="Replacement"})).Status);r=await admin.Get("/api/admin/storefront/pages");Assert.True(r.Json.AsArray().Single(x=>x!["slug"]!.GetValue<string>()==defaultSlug)!["saved"]!.GetValue<bool>());await admin.Delete("/api/admin/storefront/pages/"+defaultSlug);r=await admin.Get("/api/admin/storefront/pages");Assert.False(r.Json.AsArray().Single(x=>x!["slug"]!.GetValue<string>()==defaultSlug)!["saved"]!.GetValue<bool>());
    }

    [Fact]public async Task Cms_sections_defaults_immutable_kind_reorder_and_atomic_add()
    {
        var admin=await Admin();var r=await admin.Get("/api/admin/storefront/sections");Assert.True(r.Status==200,r.ToString());var count=r.Json["items"]!.AsArray().Count;Assert.True(count>0);Assert.Equal(count,(await admin.Get("/api/admin/storefront/sections")).Json["items"]!.AsArray().Count);
        r=await admin.Post("/api/admin/storefront/sections",new{kind="text",title="Synthetic section",config=new{body="Synthetic text"},device="mobile"});Assert.True(r.Status==201,r.ToString());var id=r.Json["id"]!.GetValue<string>();var pos=r.Json["position"]!.GetValue<int>();
        r=await admin.Put("/api/admin/storefront/sections/"+id,new{kind="not-the-real-kind",title="Updated synthetic",config=new{body="Updated body"},device="desktop",is_active=false});Assert.True(r.Status==200,r.ToString());Assert.Equal("text",r.Json["kind"]!.GetValue<string>());Assert.Equal(pos,r.Json["position"]!.GetValue<int>());Assert.False(r.Json["is_active"]!.GetValue<bool>());
        Assert.Equal("invalid_section",(await admin.Post("/api/admin/storefront/sections",new{kind="nonsense"})).ErrorCode);Assert.Equal(422,(await admin.Post("/api/admin/storefront/sections",new{kind="text",device="tablet"})).Status);Assert.Equal(404,(await admin.Put("/api/admin/storefront/sections/"+Guid.NewGuid(),new{kind="text"})).Status);
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/sections-order",new{ids=new[]{id,Guid.NewGuid().ToString(),id}})).Status);Assert.Equal(30,await ApiFactory.DbScalarAsync<int>("SELECT position FROM home_sections WHERE id=@id",new{id}));
        var before=await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM home_sections");await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_section_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='storefront.section_add' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic section rollback'; END IF; END");try{Assert.Equal(500,(await admin.Post("/api/admin/storefront/sections",new{kind="text",title="Rolled back"})).Status);Assert.Equal(before,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM home_sections"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_section_fail");}
        Assert.Equal(200,(await admin.Delete("/api/admin/storefront/sections/"+id)).Status);Assert.Equal(200,(await admin.Delete("/api/admin/storefront/sections/"+id)).Status);Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM audit_logs WHERE action='storefront.section_delete'"));
    }
    [Fact]public async Task Cms_site_theme_merge_permissions_validation_and_atomic_audit()
    {
        var admin=await Admin();var support=await Staff(admin,"sitetest@example.test","support");Assert.Equal(403,(await support.Get("/api/admin/storefront/site")).Status);Assert.Equal(403,(await support.Put("/api/admin/storefront/theme",new{theme="bazaar"})).Status);
        var r=await admin.Get("/api/admin/storefront/site");Assert.Equal("classic",r.Json["theme"]!.GetValue<string>());
        r=await admin.Put("/api/admin/storefront/site",new{brand_name="Synthetic brand",announcement=new{enabled=true,text="Synthetic announcement"}});Assert.True(r.Status==200,r.ToString());Assert.Equal("Synthetic brand",r.Json["brand_name"]!.GetValue<string>());
        r=await admin.Put("/api/admin/storefront/theme",new{theme="bazaar",settings=new{bazaar=new{preset="crimson",colors=new{primary="#9b1b30"}}}});Assert.True(r.Status==200,r.ToString());Assert.Equal("#9B1B30",r.Json["theme_settings"]!["bazaar"]!["colors"]!["primary"]!.GetValue<string>());
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/theme",new{theme="luxe",settings=new{luxe=new{preset="emerald"}}})).Status);r=await admin.Get("/api/admin/storefront/site");Assert.Equal("Synthetic brand",r.Json["brand_name"]!.GetValue<string>());Assert.Equal("Synthetic announcement",r.Json["announcement"]!["text"]!.GetValue<string>());Assert.NotNull(r.Json["theme_settings"]!["bazaar"]);Assert.NotNull(r.Json["theme_settings"]!["luxe"]);
        Assert.Equal("invalid_theme",(await admin.Put("/api/admin/storefront/theme",new{theme="neon"})).ErrorCode);Assert.Equal("invalid_site",(await admin.Put("/api/admin/storefront/site",new{colors=new{primary="red"}})).ErrorCode);Assert.Equal(422,(await admin.Put("/api/admin/storefront/theme",new{theme=new string('x',25)})).Status);Assert.Equal(422,(await admin.Put("/api/admin/storefront/theme",new{settings=new{}})).Status);
        var before=await ApiFactory.DbScalarAsync<string>("SELECT CAST(value AS CHAR) FROM platform_settings WHERE `key`='site'");await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_site_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action IN ('storefront.site','storefront.theme') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic site rollback'; END IF; END");try{Assert.Equal(500,(await admin.Put("/api/admin/storefront/site",new{brand_name="Rolled back"})).Status);Assert.Equal(before,await ApiFactory.DbScalarAsync<string>("SELECT CAST(value AS CHAR) FROM platform_settings WHERE `key`='site'"));Assert.Equal(500,(await admin.Put("/api/admin/storefront/theme",new{theme="classic"})).Status);Assert.Equal(before,await ApiFactory.DbScalarAsync<string>("SELECT CAST(value AS CHAR) FROM platform_settings WHERE `key`='site'"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_site_fail");}
        Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM audit_logs WHERE action='storefront.site'"));Assert.Equal(2,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM audit_logs WHERE action='storefront.theme'"));
    }
}
